/**
 * CPython exception + traceback surface.
 *
 * The original script never catches anything, so every rejected input reaches
 * the interpreter's default handler and is reported as a traceback on stderr
 * followed by exit status 1. This module reproduces that reporting shape:
 * an exception carries a type name, an optional detail message, and the stack
 * of frames that were active when it was raised.
 */

/** Source file names that show up in the reproduced tracebacks. */
export const SCRIPT_FILE = 'test4.py';
export const BENCODER_FILE = 'bencoder.py';

/** A raised Python exception, complete with the frames leading to it. */
export class PythonError extends Error {
  /**
   * @param {string} type exception class name, e.g. 'IndexError'
   * @param {string|null} detail message after the colon, or null for a bare
   *   exception line (a plain `assert` failure has no message)
   * @param {Array<object>} frames innermost-last, matching traceback order
   */
  constructor(type, detail, frames = []) {
    super(detail === null ? type : `${type}: ${detail}`);
    this.name = 'PythonError';
    this.type = type;
    this.detail = detail;
    this.frames = frames;
  }

  /** The final `TypeError: ...` style line of the traceback. */
  get exceptionLine() {
    return this.detail === null ? this.type : `${this.type}: ${this.detail}`;
  }
}

/**
 * Build one traceback frame.
 *
 * `source` is only available for the user script; the bundled bencoder module
 * ships without its source, so those frames print as a bare File/line/name.
 */
export function makeFrame(file, line, func, source = null, caret = null) {
  return { file, line, func, source, caret };
}

/**
 * Record an outer frame on an exception as it propagates through a call site.
 * Frames are stored outermost-first, so each caller prepends its own.
 */
export function addFrame(err, file, line, func) {
  if (err instanceof PythonError) err.frames.unshift(makeFrame(file, line, func));
  return err;
}

/** Convenience: attach a `decode_first` frame from bencoder.py. */
export function addBencoderFrame(err, line, func = 'decode_first') {
  return addFrame(err, BENCODER_FILE, line, func);
}

export function indexError(detail, frames = []) {
  return new PythonError('IndexError', detail, frames);
}

export function attributeError(detail, frames = []) {
  return new PythonError('AttributeError', detail, frames);
}

export function typeError(detail, frames = []) {
  return new PythonError('TypeError', detail, frames);
}

/** A failed bare `assert` — no detail message at all. */
export function assertionError(frames = []) {
  return new PythonError('AssertionError', null, frames);
}

export function unicodeEncodeError(detail, frames = []) {
  return new PythonError('UnicodeEncodeError', detail, frames);
}

/**
 * Render an exception exactly like CPython's default excepthook.
 * Returns the text without a trailing newline.
 */
export function formatTraceback(err) {
  const lines = ['Traceback (most recent call last):'];
  for (const frame of err.frames) {
    lines.push(`  File "${frame.file}", line ${frame.line}, in ${frame.func}`);
    if (frame.source !== null) {
      lines.push(`    ${frame.source}`);
      if (frame.caret !== null) {
        lines.push(' '.repeat(frame.caret.column) + '^'.repeat(frame.caret.width));
      }
    }
  }
  lines.push(err.exceptionLine);
  return lines.join('\n');
}

