/**
 * Python `bytes`, and the `str.encode('ascii')` codec that produces it.
 *
 * A byte string is modelled as a plain JavaScript array of integers in 0..255.
 * That mirrors CPython where indexing a `bytes` yields an *int*, not a
 * one-character value — the decoder's leftover debug `print(x[i])` prints that
 * integer, so the distinction is observable.
 */

import { indexError, unicodeEncodeError } from './pyerrors.mjs';

/** Byte values the decoder dispatches on. */
export const BYTE_i = 0x69;
export const BYTE_l = 0x6c;
export const BYTE_d = 0x64;
export const BYTE_e = 0x65;
export const BYTE_ZERO = 0x30;
export const BYTE_NINE = 0x39;

/** An immutable byte string. */
export class Bytes {
  /** @param {number[]} values byte values, each 0..255 */
  constructor(values) {
    this.values = values;
    this._text = null;
  }

  get length() {
    return this.values.length;
  }

  /**
   * Python `x[i]`. Reading past the end raises IndexError, which is how the
   * decoder reports a truncated input.
   */
  at(i) {
    if (i < 0 || i >= this.values.length) throw indexError('index out of range');
    return this.values[i];
  }

  /** Python `x.startswith(b'c', i)` — never raises, false past the end. */
  startsWith(byte, i) {
    return i >= 0 && i < this.values.length && this.values[i] === byte;
  }

  /**
   * Python `x[start:start + count]`, where `count` may be an arbitrarily large
   * integer. Slicing clamps instead of raising, so a length prefix that
   * overruns the buffer simply yields the remaining bytes.
   */
  slice(start, count) {
    const available = BigInt(Math.max(this.values.length - start, 0));
    const take = count < 0n ? 0 : Number(count < available ? count : available);
    return new Bytes(this.values.slice(start, start + take));
  }

  /**
   * Whether Python's `x[i:]` would be empty. Any index at or past the end is
   * indistinguishable from the end itself, which lets callers clamp freely.
   */
  isExhausted(i) {
    return i >= this.values.length;
  }

  /**
   * A one-char-per-byte view used for the decoder's regular expressions.
   * Built lazily and chunked so long inputs cannot overflow the call stack.
   */
  get text() {
    if (this._text === null) {
      const chunks = [];
      for (let i = 0; i < this.values.length; i += 4096) {
        chunks.push(String.fromCharCode.apply(null, this.values.slice(i, i + 4096)));
      }
      this._text = chunks.join('');
    }
    return this._text;
  }
}

/** True for byte values `0`..`9`, i.e. Python's `x[i] in b'0123456789'`. */
export function isDigitByte(byte) {
  return byte >= BYTE_ZERO && byte <= BYTE_NINE;
}

/** CPython's repr of a single unencodable character, as used in codec errors. */
function reprCodePoint(codePoint) {
  if (codePoint <= 0xff) return `'\\x${codePoint.toString(16).padStart(2, '0')}'`;
  if (codePoint <= 0xffff) return `'\\u${codePoint.toString(16).padStart(4, '0')}'`;
  return `'\\U${codePoint.toString(16).padStart(8, '0')}'`;
}

/**
 * Python `str.encode('ascii')`.
 *
 * Any code point above 127 is rejected. CPython reports the maximal run of
 * consecutive offending code points, switching to the plural "characters ...
 * position a-b" phrasing when the run is longer than one, and counts positions
 * in code points rather than UTF-16 units.
 */
export function encodeAscii(text) {
  const points = Array.from(text);
  const values = [];
  for (let i = 0; i < points.length; i++) {
    const codePoint = points[i].codePointAt(0);
    if (codePoint < 0x80) {
      values.push(codePoint);
      continue;
    }
    let end = i;
    while (end + 1 < points.length && points[end + 1].codePointAt(0) >= 0x80) end++;
    const where =
      end === i
        ? `character ${reprCodePoint(codePoint)} in position ${i}`
        : `characters in position ${i}-${end}`;
    throw unicodeEncodeError(`'ascii' codec can't encode ${where}: ordinal not in range(128)`);
  }
  return new Bytes(values);
}

