/**
 * Python `dict` semantics needed by the decoder: insertion-ordered keys, last
 * assignment wins for a repeated key while keeping its original position, and
 * a TypeError for unhashable keys.
 */

import { typeError } from './pyerrors.mjs';
import { Bytes } from './pybytes.mjs';

/** CPython type name, for the `unhashable type: '...'` message. */
function typeName(value) {
  if (value instanceof Bytes) return 'bytes';
  if (typeof value === 'bigint') return 'int';
  if (Array.isArray(value)) return 'list';
  if (value instanceof PyDict) return 'dict';
  return typeof value;
}

/**
 * A stable identity for a hashable key. Prefixes keep the int and bytes
 * namespaces apart. Returns null when the value is unhashable, matching
 * CPython where lists and dicts define no `__hash__`.
 */
function hashKey(value) {
  if (value instanceof Bytes) return `b:${value.values.join(',')}`;
  if (typeof value === 'bigint') return `i:${value}`;
  return null;
}

export class PyDict {
  constructor() {
    /** @type {Map<string, {key: unknown, value: unknown}>} insertion-ordered */
    this.entries = new Map();
  }

  get size() {
    return this.entries.size;
  }

  /** Python `d[key] = value`; raises TypeError for an unhashable key. */
  set(key, value) {
    const id = hashKey(key);
    if (id === null) throw typeError(`unhashable type: '${typeName(key)}'`);
    const existing = this.entries.get(id);
    if (existing === undefined) this.entries.set(id, { key, value });
    else existing.value = value;
    return this;
  }

  /** Key/value pairs in insertion order. */
  *pairs() {
    for (const entry of this.entries.values()) yield [entry.key, entry.value];
  }

  /**
   * Python `dict(zip(items[::2], items[1::2]))`: consecutive items are paired
   * up and a trailing unpaired item is dropped, because `zip` stops at the
   * shorter side. A dangling key is therefore never hashed.
   */
  static fromFlatItems(items) {
    const dict = new PyDict();
    for (let i = 0; i + 1 < items.length; i += 2) dict.set(items[i], items[i + 1]);
    return dict;
  }
}

