/**
 * Python's `repr`/`str` for the value shapes the decoder can return: `bytes`,
 * `int`, `list` and `dict`. `print(x)` uses `str(x)`, which for every one of
 * these delegates to `repr` (containers always repr their members), so a single
 * formatter covers the script's output.
 */

import { Bytes } from './pybytes.mjs';
import { PyDict } from './pydict.mjs';

const QUOTE_SINGLE = 0x27;
const QUOTE_DOUBLE = 0x22;
const BACKSLASH = 0x5c;

/** Escapes CPython spells with a letter rather than a hex code. */
const NAMED_ESCAPES = new Map([
  [0x09, '\\t'],
  [0x0a, '\\n'],
  [0x0d, '\\r'],
]);

/**
 * Python `repr(bytes)`.
 *
 * The quote character is single unless the value contains a single quote and no
 * double quote, in which case double quotes avoid escaping. When both appear,
 * single quotes are kept and the embedded one is escaped.
 */
export function reprBytes(value) {
  const hasSingle = value.values.includes(QUOTE_SINGLE);
  const hasDouble = value.values.includes(QUOTE_DOUBLE);
  const quote = hasSingle && !hasDouble ? QUOTE_DOUBLE : QUOTE_SINGLE;
  const quoteChar = String.fromCharCode(quote);

  let body = '';
  for (const byte of value.values) {
    if (byte === BACKSLASH || byte === quote) body += '\\' + String.fromCharCode(byte);
    else if (NAMED_ESCAPES.has(byte)) body += NAMED_ESCAPES.get(byte);
    else if (byte < 0x20 || byte > 0x7e) body += `\\x${byte.toString(16).padStart(2, '0')}`;
    else body += String.fromCharCode(byte);
  }
  return `b${quoteChar}${body}${quoteChar}`;
}

/** Python `repr(value)`. */
export function pyRepr(value) {
  if (value instanceof Bytes) return reprBytes(value);
  if (typeof value === 'bigint') return value.toString();
  if (Array.isArray(value)) return `[${value.map(pyRepr).join(', ')}]`;
  if (value instanceof PyDict) {
    const parts = [];
    for (const [key, item] of value.pairs()) parts.push(`${pyRepr(key)}: ${pyRepr(item)}`);
    return `{${parts.join(', ')}}`;
  }
  return String(value);
}

/** Python `str(value)` — identical to `repr` for every value produced here. */
export function pyStr(value) {
  return pyRepr(value);
}

