/** Python's `print` and the interpreter's stderr reporting, on Node streams. */

import { formatTraceback } from './pyerrors.mjs';

/** Python `print(text)` — writes the text plus a newline to stdout. */
export function printLine(text) {
  process.stdout.write(`${text}\n`);
}

/** Write a line to stderr. */
export function printErrorLine(text) {
  process.stderr.write(`${text}\n`);
}

/**
 * Report an uncaught exception the way the frozen script does: CPython's
 * traceback, then the PyInstaller bootloader's own complaint (which carries the
 * live process id).
 */
export function reportUncaught(err, scriptName) {
  printErrorLine(formatTraceback(err));
  printErrorLine(`[PYI-${process.pid}:ERROR] Failed to execute script '${scriptName}' due to unhandled exception!`);
}

