/**
 * The `bencoder` decoder, reimplemented from its observed behaviour.
 *
 * Two traits set it apart from a textbook bencode reader, and both are load
 * bearing for output equality:
 *
 *  - A string's length prefix is applied as a Python slice, so a prefix longer
 *    than the remaining input yields whatever is left instead of failing
 *    (`9:value` decodes to `b'value'`). A prefix that is too *short* leaves
 *    trailing bytes, which the top level rejects as malformed.
 *  - Lists and dicts are read into one flat item list; a dict is then built with
 *    `dict(zip(items[::2], items[1::2]))`, so a dangling final key is silently
 *    dropped (`d3:cowe` decodes to `{}`).
 *
 * A leftover debug `print` in the unknown-prefix branch writes the offending
 * byte value to stdout before the assertion fires, so that path produces output
 * on stdout *and* a traceback.
 */

import {
  BENCODER_FILE,
  addBencoderFrame,
  assertionError,
  attributeError,
  typeError,
} from './pyerrors.mjs';
import { BYTE_d, BYTE_e, BYTE_i, BYTE_l, isDigitByte } from './pybytes.mjs';
import { PyDict } from './pydict.mjs';
import { printLine } from './stdio.mjs';

/**
 * Line numbers inside bencoder.py, kept so the reproduced tracebacks name the
 * same frames as the original.
 */
const LINE_INT_GROUP = 67;
const LINE_RECURSE = 72;
const LINE_BUILD_DICT = 78;
const LINE_DIGIT_TEST = 79;
const LINE_STR_GROUP = 81;
const LINE_ASSERT = 88;
const LINE_DECODE_CALL = 93;
const LINE_MALFORMED = 95;

/** Sticky so each match is anchored at the current offset. */
const INTEGER_PATTERN = /i(-?\d+)e/y;
const STRING_PATTERN = /(\d+):/y;

/** The AttributeError raised when a regex fails to match and `.group` is called. */
function noMatchError(line) {
  return attributeError("'NoneType' object has no attribute 'group'", [
    { file: BENCODER_FILE, line, func: 'decode_first', source: null, caret: null },
  ]);
}

function matchAt(pattern, x, i) {
  pattern.lastIndex = i;
  return pattern.exec(x.text);
}

/**
 * Decode one value starting at `i`.
 *
 * @param {import('./pybytes.mjs').Bytes} x
 * @param {number} i
 * @returns {[unknown, number]} the value and the offset just past it, clamped
 *   to the input length (every offset at or past the end behaves alike)
 */
function decodeFirst(x, i) {
  if (x.startsWith(BYTE_i, i)) {
    const match = matchAt(INTEGER_PATTERN, x, i);
    if (match === null) throw noMatchError(LINE_INT_GROUP);
    return [BigInt(match[1]), i + match[0].length];
  }

  if (x.startsWith(BYTE_l, i) || x.startsWith(BYTE_d, i)) {
    const isDict = x.startsWith(BYTE_d, i);
    const items = [];
    let at = i + 1;
    while (!x.startsWith(BYTE_e, at)) {
      let item;
      try {
        [item, at] = decodeFirst(x, at);
      } catch (err) {
        throw addBencoderFrame(err, LINE_RECURSE);
      }
      items.push(item);
    }
    const after = at + 1;
    if (!isDict) return [items, after];
    try {
      return [PyDict.fromFlatItems(items), after];
    } catch (err) {
      throw addBencoderFrame(err, LINE_BUILD_DICT);
    }
  }

  let head;
  try {
    head = x.at(i);
  } catch (err) {
    throw addBencoderFrame(err, LINE_DIGIT_TEST);
  }

  if (isDigitByte(head)) {
    const match = matchAt(STRING_PATTERN, x, i);
    if (match === null) throw noMatchError(LINE_STR_GROUP);
    const start = i + match[0].length;
    const count = BigInt(match[1]);
    const value = x.slice(start, count);
    return [value, Math.min(start + value.length, x.length)];
  }

  // bencoder.py line 87: a debug print left in the unknown-prefix branch.
  printLine(String(head));
  throw assertionError([
    { file: BENCODER_FILE, line: LINE_ASSERT, func: 'decode_first', source: null, caret: null },
  ]);
}

/**
 * `bencoder.decode(x)` — decode one value and require that it consumed the
 * whole input.
 *
 * @param {import('./pybytes.mjs').Bytes} x
 */
export function decode(x) {
  let value;
  let at;
  try {
    [value, at] = decodeFirst(x, 0);
  } catch (err) {
    throw addBencoderFrame(err, LINE_DECODE_CALL, 'decode');
  }
  if (!x.isExhausted(at)) {
    throw typeError('Malformed input.', [
      { file: BENCODER_FILE, line: LINE_MALFORMED, func: 'decode', source: null, caret: null },
    ]);
  }
  return value;
}

