/**
 * The slice of Python's `argparse` that this CLI exercises.
 *
 * Behaviours that are reproduced because they are observable:
 *  - `--opt value` and `--opt=value` both work, and a repeated option wins last.
 *  - A missing value reports `argument --a: expected one argument`. Whether the
 *    next token counts as a value depends on argparse's negative-number rule: a
 *    lone `-`, or something like `-5` / `-5.5`, is a value, while `-1:a` is
 *    treated as an option string and therefore not consumed.
 *  - Long options may be abbreviated (`--he` resolves to `--help`).
 *  - `-h` prints help to stdout and exits 0 as soon as it is seen.
 *  - Missing required options are reported *before* unrecognized ones, so an
 *    undefined option such as `-a` surfaces as the required-argument error.
 *  - Errors print usage plus a message to stderr and exit with status 2.
 */

/** argparse's `_negative_number_matcher`. */
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

const HELP_INDENT = 2;
const MAX_HELP_POSITION = 24;

/** Raised for anything that makes argparse call `parser.error()`. */
export class ArgumentParserError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ArgumentParserError';
  }
}

/** Signals that `-h` was seen and usage has to be printed on stdout. */
export class HelpRequested extends Error {
  constructor() {
    super('help requested');
    this.name = 'HelpRequested';
  }
}

export class ArgumentParser {
  /** @param {{prog: string}} options */
  constructor({ prog }) {
    this.prog = prog;
    /** @type {Array<object>} declared optionals, in declaration order */
    this.actions = [];
    this.addArgument(['-h', '--help'], {
      action: 'help',
      help: 'show this help message and exit',
    });
  }

  /**
   * Declare an optional argument.
   *
   * @param {string[]} flags option strings, e.g. `['--a']`
   * @param {{action?: string, required?: boolean, metavar?: string, help?: string}} options
   */
  addArgument(flags, options = {}) {
    const action = options.action ?? 'store';
    const dest = flags[flags.length - 1].replace(/^--?/, '');
    this.actions.push({
      flags,
      dest,
      action,
      required: options.required ?? false,
      metavar: options.metavar ?? dest.toUpperCase(),
      help: options.help ?? null,
    });
    return this;
  }

  /** `usage: prog [-h] --a A` */
  formatUsage() {
    const parts = this.actions.map((action) => {
      const body =
        action.action === 'store' ? `${action.flags[0]} ${action.metavar}` : action.flags[0];
      return action.required ? body : `[${body}]`;
    });
    return `usage: ${[this.prog, ...parts].join(' ')}`;
  }

  /**
   * Full `--help` text. The help column is placed the way argparse's
   * HelpFormatter places it: two past the widest invocation, capped at 24.
   */
  formatHelp() {
    const invocations = this.actions.map((action) =>
      action.action === 'store'
        ? action.flags.map((flag) => `${flag} ${action.metavar}`).join(', ')
        : action.flags.join(', '),
    );
    const maxLength = Math.max(...invocations.map((text) => text.length + HELP_INDENT));
    const helpPosition = Math.min(maxLength + 2, MAX_HELP_POSITION);
    const width = helpPosition - HELP_INDENT - 2;

    const lines = [this.formatUsage(), '', 'options:'];
    this.actions.forEach((action, index) => {
      const invocation = invocations[index];
      if (action.help === null) lines.push(`${' '.repeat(HELP_INDENT)}${invocation}`);
      else {
        lines.push(
          `${' '.repeat(HELP_INDENT)}${invocation.padEnd(width)}  ${action.help}`,
        );
      }
    });
    return lines.join('\n');
  }

  /** Whether a token should be read as an option rather than a value. */
  #looksLikeOption(token) {
    if (!token.startsWith('-') || token === '-') return false;
    return !NEGATIVE_NUMBER.test(token);
  }

  /**
   * Resolve an option string, allowing unambiguous abbreviation of long forms.
   * Returns null when nothing matches.
   */
  #findAction(name) {
    for (const action of this.actions) {
      if (action.flags.includes(name)) return action;
    }
    if (!name.startsWith('--')) return null;
    const candidates = this.actions.filter((action) =>
      action.flags.some((flag) => flag.startsWith('--') && flag.startsWith(name)),
    );
    return candidates.length === 1 ? candidates[0] : null;
  }

  /**
   * Parse `argv` (option/value tokens only, without the program name).
   *
   * @throws {HelpRequested} when `-h` is present
   * @throws {ArgumentParserError} on any usage error
   */
  parseArgs(argv) {
    const values = new Map();
    const extras = [];
    let optionsEnded = false;

    for (let i = 0; i < argv.length; i++) {
      const token = argv[i];

      if (optionsEnded || !this.#looksLikeOption(token)) {
        if (token === '--' && !optionsEnded) {
          optionsEnded = true;
          continue;
        }
        extras.push(token);
        continue;
      }
      if (token === '--') {
        optionsEnded = true;
        continue;
      }

      const equals = token.indexOf('=');
      const name = equals === -1 ? token : token.slice(0, equals);
      const action = this.#findAction(name);
      if (action === null) {
        extras.push(token);
        continue;
      }
      if (action.action === 'help') throw new HelpRequested();

      if (equals !== -1) {
        values.set(action.dest, token.slice(equals + 1));
        continue;
      }
      const next = argv[i + 1];
      if (next === undefined || this.#looksLikeOption(next)) {
        throw new ArgumentParserError(`argument ${name}: expected one argument`);
      }
      values.set(action.dest, next);
      i++;
    }

    const missing = this.actions.filter(
      (action) => action.required && !values.has(action.dest),
    );
    if (missing.length > 0) {
      const names = missing.map((action) => action.flags[0]).join(', ');
      throw new ArgumentParserError(`the following arguments are required: ${names}`);
    }
    if (extras.length > 0) {
      throw new ArgumentParserError(`unrecognized arguments: ${extras.join(' ')}`);
    }

    return Object.fromEntries(values);
  }
}

