/**
 * Node port of test4.py:
 *
 *     import argparse
 *     import bencoder
 *
 *     parser = argparse.ArgumentParser()
 *     parser.add_argument('--a', type=str, required=True)
 *     args = parser.parse_args()
 *
 *     result = bencoder.decode(args.a.encode('ascii'))  # Decode bencoded string
 *     print(result)
 *
 * Run as: node test4.mjs --a '9:value'
 */

import { basename } from 'node:path';

import { ArgumentParser, ArgumentParserError, HelpRequested } from './lib/argparse.mjs';
import { decode } from './lib/bencode.mjs';
import { encodeAscii } from './lib/pybytes.mjs';
import { PythonError, SCRIPT_FILE, makeFrame } from './lib/pyerrors.mjs';
import { pyStr } from './lib/pyrepr.mjs';
import { printErrorLine, printLine, reportUncaught } from './lib/stdio.mjs';

/** Line 8 of the original script, as the traceback would show it. */
const STATEMENT_LINE = 8;
const STATEMENT_SOURCE =
  "result = bencoder.decode(args.a.encode('ascii'))  # Decode bencoded string";
const DECODE_EXPRESSION = "bencoder.decode(args.a.encode('ascii'))";
const ENCODE_EXPRESSION = "args.a.encode('ascii')";

/** Traceback source lines are re-indented to four spaces; carets follow suit. */
const TRACEBACK_INDENT = 4;

/** Locate the sub-expression the carets underline, the way CPython does. */
function caretFor(expression) {
  return {
    column: TRACEBACK_INDENT + STATEMENT_SOURCE.indexOf(expression),
    width: expression.length,
  };
}

/** The `File "test4.py", line 8, in <module>` frame, with its caret span. */
function statementFrame(expression) {
  return makeFrame(
    SCRIPT_FILE,
    STATEMENT_LINE,
    '<module>',
    STATEMENT_SOURCE,
    caretFor(expression),
  );
}

function buildParser(prog) {
  const parser = new ArgumentParser({ prog });
  parser.addArgument(['--a'], { required: true });
  return parser;
}

function main(argv) {
  const parser = buildParser(basename(process.argv[1] ?? 'test4.mjs'));

  let args;
  try {
    args = parser.parseArgs(argv);
  } catch (err) {
    if (err instanceof HelpRequested) {
      printLine(parser.formatHelp());
      process.exitCode = 0;
      return;
    }
    if (err instanceof ArgumentParserError) {
      printErrorLine(parser.formatUsage());
      printErrorLine(`${parser.prog}: error: ${err.message}`);
      process.exitCode = 2;
      return;
    }
    throw err;
  }

  // `args.a.encode('ascii')` and the `bencoder.decode(...)` call around it are
  // separate sub-expressions of one statement, so each gets its own caret span.
  let raw;
  try {
    raw = encodeAscii(args.a);
  } catch (err) {
    if (!(err instanceof PythonError)) throw err;
    err.frames.unshift(statementFrame(ENCODE_EXPRESSION));
    reportUncaught(err, 'test4');
    process.exitCode = 1;
    return;
  }

  let result;
  try {
    result = decode(raw);
  } catch (err) {
    if (!(err instanceof PythonError)) throw err;
    err.frames.unshift(statementFrame(DECODE_EXPRESSION));
    reportUncaught(err, 'test4');
    process.exitCode = 1;
    return;
  }

  printLine(pyStr(result));
}

main(process.argv.slice(2));

