/**
 * CPython's `linecache`, as tracebacks use it.
 *
 * A traceback frame stores only the *recorded* file name — here the bare
 * `test4.py` — and the source line is fetched at display time by resolving that
 * name against the current working directory. When the file cannot be found the
 * frame prints without a source or caret line, which is why the same failing
 * input produces a shorter traceback when run from a different directory.
 */

import { readFileSync } from 'node:fs';

/** @type {Map<string, string[]|null>} */
const cache = new Map();

/**
 * Return one 1-based line of `filename`, or null when it is unavailable.
 * Trailing newlines are not included.
 */
export function getLine(filename, lineNumber) {
  if (!cache.has(filename)) {
    let lines = null;
    try {
      lines = readFileSync(filename, 'utf8').split('\n');
    } catch {
      lines = null;
    }
    cache.set(filename, lines);
  }
  const lines = cache.get(filename);
  if (lines === null || lineNumber < 1 || lineNumber > lines.length) return null;
  return lines[lineNumber - 1].replace(/\r$/, '');
}

