#!/usr/bin/env node
/**
 * Randomized differential fuzz: feed the same input to the frozen Python
 * executable and to the Node port, and compare stdout, stderr and exit status.
 * The PyInstaller pid in the bootloader message is normalized away.
 */

import { execFileSync } from 'node:child_process';

const PY = '/workspace/dataset/test4_executable';
const JS = '/output/test4.mjs';

function run(cmd, args) {
  const result = { out: '', err: '', code: 0 };
  try {
    result.out = execFileSync(cmd, args, { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] });
  } catch (err) {
    result.out = err.stdout ?? '';
    result.err = err.stderr ?? '';
    result.code = err.status ?? 1;
    return normalize(result);
  }
  return normalize(result);
}

function normalize(result) {
  result.err = result.err.replace(/\[PYI-\d+:/g, '[PYI-PID:');
  return result;
}

let seed = Number(process.argv[3] ?? 12345);
function rand(n) {
  // xorshift, so runs are reproducible from the seed
  seed ^= seed << 13;
  seed ^= seed >>> 17;
  seed ^= seed << 5;
  seed |= 0;
  return Math.abs(seed) % n;
}
const pick = (list) => list[rand(list.length)];

const ALPHABET = 'abcXYZ019:ile-d.\t\n\r\\\'" ~\x01\x7f';

/** A syntactically plausible value, sometimes with a deliberately wrong length. */
function makeValue(depth) {
  switch (rand(depth > 2 ? 2 : 5)) {
    case 0: {
      const body = Array.from({ length: rand(5) }, () => pick([...ALPHABET])).join('');
      const declared = body.length + [0, 0, 0, 1, -1, 4, 20][rand(7)];
      return `${Math.max(declared, 0)}:${body}`;
    }
    case 1:
      return `i${rand(2) ? '' : '-'}${rand(1000)}e`;
    case 2:
      return `l${Array.from({ length: rand(3) }, () => makeValue(depth + 1)).join('')}e`;
    case 3:
      return `d${Array.from({ length: rand(4) }, () => makeValue(depth + 1)).join('')}e`;
    default:
      return pick(['le', 'de', 'i0e', '0:', 'e', '', 'x']);
  }
}

/** Random noise, to probe the malformed paths. */
function makeGarbage() {
  return Array.from({ length: rand(9) }, () => pick([...ALPHABET])).join('');
}

const iterations = Number(process.argv[2] ?? 300);
let pass = 0;
const failures = [];

for (let i = 0; i < iterations; i++) {
  const input = i % 3 === 2 ? makeGarbage() : makeValue(0);
  const py = run(PY, ['--a', input]);
  const js = run('node', [JS, '--a', input]);
  if (py.out === js.out && py.err === js.err && py.code === js.code) pass++;
  else failures.push({ input, py, js });
}

for (const failure of failures.slice(0, 5)) {
  console.log(`\n### MISMATCH input=${JSON.stringify(failure.input)}`);
  console.log(`  py code=${failure.py.code} out=${JSON.stringify(failure.py.out)}`);
  console.log(`  js code=${failure.js.code} out=${JSON.stringify(failure.js.out)}`);
  if (failure.py.err !== failure.js.err) {
    console.log(`  py err=${JSON.stringify(failure.py.err)}`);
    console.log(`  js err=${JSON.stringify(failure.js.err)}`);
  }
}
console.log(`\n=== fuzz pass=${pass}/${iterations} fail=${failures.length} ===`);
process.exitCode = failures.length === 0 ? 0 : 1;

