  /**
   * argparse's `_parse_optional`: decide whether a token is an option and, if
   * so, which action and inline value it carries.
   *
   * Returns null when the token is to be read as a plain value. The order of
   * these tests is argparse's own and is observable: an exact option match wins
   * over everything, a lone `-` is a value, something matching the
   * negative-number pattern is a value, and — easy to miss — any token
   * containing a space is a value too.
   *
   * @returns {{action: object|null, name: string, inlineValue: string|null}|null}
   */
  #parseOptional(token) {
    if (token === '') return null;
    if (!token.startsWith('-')) return null;

    const exact = this.actions.find((action) => action.flags.includes(token));
    if (exact !== undefined) return { action: exact, name: token, inlineValue: null };

    if (token.length === 1) return null;

    const equals = token.indexOf('=');
    if (equals !== -1) {
      const name = token.slice(0, equals);
      const named = this.actions.find((action) => action.flags.includes(name));
      if (named !== undefined) {
        return { action: named, name, inlineValue: token.slice(equals + 1) };
